<div class="page-heading"><div><div class="eyebrow">YOUR VISUAL LIBRARY</div><h1>A place for every image.</h1><p><?=$total?> files · Images, documents, and videos in one place.</p></div></div><section class="panel upload-panel"><form action="<?=e(cms_url('/admin/upload'))?>" method="post" enctype="multipart/form-data" class="upload-zone" data-upload-zone><?=csrf_field()?><span class="upload-icon">↥</span><h2>Drop your files here</h2><p>JPEG, PNG, WebP, GIF, PDF, MP4 or WebM · Up to <?=e(cms_config('UPLOAD_MAX_MB','25'))?> MB each</p><label class="button">Choose files<input type="file" name="files[]" multiple required hidden accept="image/jpeg,image/png,image/gif,image/webp,application/pdf,video/mp4,video/webm"></label><button class="button secondary" type="submit">Upload selected files</button><progress max="100" value="0" hidden></progress><div class="upload-status" role="status"></div></form></section><section class="panel"><form class="list-toolbar"><label class="search-field"><span>⌕</span><input name="q" type="search" placeholder="Search your media…" aria-label="Search media" value="<?=e($q)?>"></label><select name="type" aria-label="File type"><option value="">All file types</option><?php foreach(['image'=>'Images','application'=>'Documents','video'=>'Videos'] as $value=>$label):?><option value="<?=$value?>" <?=(request()->query()['type']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach?></select><button class="button secondary">Filter</button></form><div class="media-grid"><?php foreach($rows as $row):?><article class="media-card"><a class="media-thumb" href="<?=e(cms_url('/admin/media_files/'.$row['id']))?>"><?php if(str_starts_with($row['mime_type'],'image/')):?><?=media_img($row['id'],$row['title'])?><?php else:?><span><?=str_starts_with($row['mime_type'],'video/')?'▷':'PDF'?></span><?php endif?></a><div class="media-card-copy"><h3><?=e($row['title'])?></h3><p><?=e($row['mime_type'])?> · <?=number_format($row['size_bytes']/1024)?> KB</p><div class="actions"><a class="text-link" href="<?=e(cms_url('/admin/media_files/'.$row['id']))?>">Edit</a><button type="button" class="text-button" data-copy="<?=e(App\Services\Media::url((int)$row['id']))?>">Copy URL</button><form method="post" action="<?=e(cms_url('/admin/media_files/'.$row['id'].'/delete'))?>" data-confirm="Delete this file permanently? Files still referenced by content cannot be deleted."><?=csrf_field()?><button class="text-button danger-text">Delete</button></form></div></div></article><?php endforeach?></div><?php if(!$rows):?><div class="empty-state"><span>◫</span><h2>No files found</h2><p>Upload your media or try a different search.</p></div><?php endif?><?php cms_view('admin/pagination',compact('total','page','perPage'));?></section>
